contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint depositAmount, uint collectAmount) public payable {
        require(address(this).balance >= depositAmount, "insufficient balance for deposit");
        require(depositAmount > 0, "deposit amount must be positive");
        require(collectAmount > 0, "collect amount must be positive");

        uint beforeBalance = c.balances(address(this));
        uint beforeContractBalance = address(c).balance;

        c.Deposit{value: depositAmount}();

        uint afterDepositBalance = c.balances(address(this));

        require(collectAmount <= afterDepositBalance, "collect exceeds balance");

        bool collectReverted;
        try c.Collect(collectAmount) {
            collectReverted = false;
        } catch {
            collectReverted = true;
        }

        uint finalBalance = c.balances(address(this));
        uint finalContractBalance = address(c).balance;

        if (collectReverted) {
            assert(finalBalance == afterDepositBalance && finalContractBalance == beforeContractBalance + depositAmount);
        } else {
            assert(finalBalance == beforeBalance && finalContractBalance == beforeContractBalance);
        }
    }

    receive() external payable {}
}

