contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint depositAmount, uint collectAmount) public payable {
        require(address(this).balance >= depositAmount);
        c.Deposit{value: depositAmount}();

        uint balBefore = c.balances(address(this));
        uint minSum = c.MinSum();

        // Try to collect an amount that is less than MinSum (the contract's own rule) but at most the sender's balance.
        // The contract should not change the balance in this case.
        bool reverted;
        if (collectAmount < minSum && collectAmount <= balBefore) {
            try c.Collect(collectAmount) { reverted = false; } catch { reverted = true; }
        } else {
            // If the precondition for the test does not hold, we don't call Collect.
            return;
        }

        uint balAfter = c.balances(address(this));

        assert(balAfter == balBefore);
    }

    receive() external payable {}
}

